 public static boolean owns(String id){return SKILLS.contains(id);}public static boolean held(String id){return JET.equals(id)||MISSILE.equals(id);}
 public static long startLocal(String id){if(!owns(id))return 0;Minecraft mc=Minecraft.getInstance();sync(mc);clock(mc);Context old=mc.player==null?null:CONTEXTS.get(id).remove(mc.player.getId());if(old!=null){TOKENS.get(id).end(old.key,old.token);old.hide();}long n=INPUTS.get(id).press();NONCES.put(id,n);ABORTED.remove(id);return n;}
