 public static void endLocal(String id){if(!owns(id))return;Minecraft mc=Minecraft.getInstance();sync(mc);INPUTS.get(id).end();ABORTED.put(id,true);Context c=mc.player==null?null:CONTEXTS.get(id).get(mc.player.getId());if(c!=null&&held(id))c.hide();}
 public static void releaseLocal(String id){if(!owns(id))return;Minecraft mc=Minecraft.getInstance();sync(mc);INPUTS.get(id).end();ABORTED.put(id,false);Context c=mc.player==null?null:CONTEXTS.get(id).get(mc.player.getId());if(c!=null){c.marking=false;if(MISSILE.equals(id))c.hide();}}
