 public static void fragments(Vec3 at){Minecraft mc=Minecraft.getInstance();sync(mc);if(mc.level==null)return;int count=18+RANDOM.nextInt(27-18);for(int i=0;i<count&&PARTICLES.size()<4096;i++){double speed=random(.08,.18),sq=speed*speed,x=RANDOM.nextDouble()*speed,y=RANDOM.nextDouble()*Math.sqrt(sq-x*x),z=Math.sqrt(Math.max(0,sq-x*x-y*y));x*=RANDOM.nextBoolean()?1:-1;y*=RANDOM.nextBoolean()?1:-1;z*=RANDOM.nextBoolean()?1:-1;PARTICLES.add(new Particle(at,new Vec3(x,y+.2,z),true));}}
 private static void addParticle(Vec3 p,Vec3 v,boolean fragment){if(PARTICLES.size()<4096)PARTICLES.add(new Particle(p,v,fragment));}
 private static final class Particle{Vec3 position,previous,velocity;final boolean fragment;final int life;final double opacity;final float size;float yaw,pitch;int age;Particle(Vec3 p,Vec3 v,boolean f){position=previous=p;velocity=v;fragment=f;life=f?10000000:25+RANDOM.nextInt(30);opacity=f?1:random(.3,.6);size=f?.1F:.05F+RANDOM.nextFloat()*(.07F-.05F);if(f){yaw=RANDOM.nextFloat()*360;pitch=-90+RANDOM.nextFloat()*180;}}boolean tick(){age++;previous=position;position=position.add(velocity);if(fragment){velocity=velocity.add(0,-.03,0);yaw+=FRAGMENT_YAW_RATE;pitch+=FRAGMENT_PITCH_RATE;}return fragment?age<=life:ClassicMeltdownerStarterTimeline.particleAlive(age,life);}double alpha(){return opacity*(fragment?Math.min(1,age/5.0):ClassicMeltdownerStarterTimeline.particleAlpha(age,life));}}
 private static final class Ball{final Vec3 offset;final long created;final Random random=new Random();final ClassicMeltdownerStarterTimeline.BallWiggle wiggle=new ClassicMeltdownerStarterTimeline.BallWiggle();Ball(Vec3 p,long c){offset=p;created=c;}}
 private static final class Context{final Player caster;final String skill;final ClientLevel level;final Object connection;final Caster key;final long token,nonce,created;final boolean local;boolean shown,marking,triggering,preRay,scatter;int ticks,flightTicks;long triggerAt;Vec3 target;final BitSet ballIndices=new BitSet(21);final Map<Integer,Ball> balls=new LinkedHashMap<>();final ParticleSequence updates=new ParticleSequence(),attacks=new ParticleSequence(),steps=new ParticleSequence();Context(Player p,String s,ClientLevel l,Object con,long t,long n,boolean show,boolean local){caster=p;skill=s;level=l;connection=con;key=new Caster(p.getId(),p.getUUID());token=t;nonce=n;created=CLOCK.elapsed();shown=show;this.local=local;marking=JET.equals(s);}boolean valid(Minecraft mc){return level==mc.level&&connection==mc.getConnection()&&ClassicMeltdownerLateEffects.valid(mc,caster)&&key.uuid().equals(caster.getUUID());}void hide(){if(local&&triggering&&shown)caster.getAbilities().setWalkingSpeed(RESTORE_WALK);shown=marking=false;balls.clear();}}
 private static final class Ray{final Player caster;final UUID uuid;final ClientLevel level;final Object connection;final Vec3 origin;final List<Vec3> directions;final double length;final Spec spec;final long created;int ticks;final ClassicMeltdownerStarterTimeline.RayWiggle wiggle=new ClassicMeltdownerStarterTimeline.RayWiggle();Ray(Context c,Vec3 p,List<Vec3> d,double len,Spec s,long time){caster=c.caster;uuid=c.key.uuid();level=c.level;connection=c.connection;origin=p;directions=List.copyOf(d);length=len;spec=s;created=time;}boolean valid(Minecraft mc){return level==mc.level&&connection==mc.getConnection()&&ClassicMeltdownerLateEffects.valid(mc,caster)&&caster.getUUID().equals(uuid);}}
 private static final class RaySound extends AbstractTickableSoundInstance{final Ray ray;boolean finished;RaySound(Ray ray,float volume){super(SoundEvent.createVariableRangeEvent(ResourceLocation.fromNamespaceAndPath("academy",RAY_SOUND)),SoundSource.MASTER,RandomSource.create());this.ray=ray;this.volume=volume;pitch=1;looping=false;x=ray.origin.x;y=ray.origin.y;z=ray.origin.z;}void finish(){finished=true;stop();}@Override public void tick(){if(finished||!ray.valid(Minecraft.getInstance()))finish();}}
 private static boolean index(CompoundTag t,int a,int b){return t.contains("index",Tag.TAG_INT)&&t.getInt("index")>=a&&t.getInt("index")<=b;}
 private static boolean vectorTags(CompoundTag t,String x,String y,String z){return t.contains(x,Tag.TAG_DOUBLE)&&t.contains(y,Tag.TAG_DOUBLE)&&t.contains(z,Tag.TAG_DOUBLE)&&Double.isFinite(t.getDouble(x))&&Double.isFinite(t.getDouble(y))&&Double.isFinite(t.getDouble(z));}
 private static Vec3 vec(CompoundTag t,String x,String y,String z){return new Vec3(t.getDouble(x),t.getDouble(y),t.getDouble(z));}private static ClassicMeltdownerStarterTimeline.Point p(Vec3 p){return new ClassicMeltdownerStarterTimeline.Point(p.x,p.y,p.z);}private static Vec3 vec(ClassicMeltdownerStarterTimeline.Point p){return new Vec3(p.x(),p.y(),p.z());}private static Point point(Vec3 p){return new Point(p.x,p.y,p.z);}private static Vec3 v(Point p){return new Vec3(p.x(),p.y(),p.z());}private static Vec3 v(ClassicMeltdownerStarterTimeline.Point p){return vec(p);}private static double random(double a,double b){return a+RANDOM.nextDouble()*(b-a);}private static ResourceLocation texture(String p){return ResourceLocation.fromNamespaceAndPath("academy","textures/"+p+".png");}private static ResourceLocation[] seq(String p,int count){ResourceLocation[] a=new ResourceLocation[count];for(int i=0;i<count;i++)a[i]=texture(p+i);return a;}
 private static final class Material extends RenderType{private record Key(ResourceLocation t,int shader,boolean cull,boolean overlay){}private static final Map<Key,RenderType> TYPES=new HashMap<>();private Material(String n,VertexFormat f,VertexFormat.Mode m,int s,boolean cr,boolean sort,Runnable set,Runnable reset){super(n,f,m,s,cr,sort,set,reset);}static RenderType type(ResourceLocation t,int shader,boolean cull,boolean overlay){return TYPES.computeIfAbsent(new Key(t,shader,cull,overlay),key->create("academy_classic_late_"+key.t.getPath()+"_"+shader+"_"+cull+"_"+overlay,DefaultVertexFormat.POSITION_TEX_COLOR,VertexFormat.Mode.QUADS,4096,false,false,CompositeState.builder().setShaderState(new ShaderStateShard(shader==2?GameRenderer::getPositionTexColorShader:shader==1?ClassicMeltdownerStarterEffects.CutoffShader::get:ClassicMeltdownerStarterEffects.CutoffShader::zero)).setTextureState(new TextureStateShard(t,false,false)).setTransparencyState(TRANSLUCENT_TRANSPARENCY).setCullState(cull?CULL:NO_CULL).setDepthTestState(overlay?NO_DEPTH_TEST:LEQUAL_DEPTH_TEST).setWriteMaskState(overlay?COLOR_WRITE:COLOR_DEPTH_WRITE).setLightmapState(NO_LIGHTMAP).setOverlayState(NO_OVERLAY).setOutputState(PARTICLES_TARGET).createCompositeState(false)));}}
